    """
    Find the shortest path from start to end in an unweighted graph using BFS.

    Args:
        graph: Adjacency list representation of the graph.
        start: The starting node.
        end: The target node.

    Returns:
        A list representing the shortest path from start to end, or None if no path exists.
    """
    if start == end:
        return [start]

    if start not in graph:
        return None

    # Queue for BFS: stores nodes to visit
    queue = deque([start])

    # Visited set to avoid cycles and redundant processing
    visited: Set[Any] = {start}

    # Parent map to reconstruct the path
    parent: Dict[Any, Any] = {start: None}

    while queue:
        current = queue.popleft()

        # If we reached the target, reconstruct path
        if current == end:
            path = []
            node = end
            while node is not None:
                path.append(node)
                node = parent[node]
            return path[::-1]

        # Explore neighbors
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = current
                queue.append(neighbor)

    return None

